/* Personagem do aluno: 16 retratos em pixel art 128 × 128, no traço da Isa (8 femininos e 8 masculinos).
   Pele, cabelo e olhos são recoloridos em tempo real a partir de máscaras; os óculos são desenhados na
   posição dos olhos de cada retrato. Guarda só a receita (personagem, cores, óculos e fundo). */
const AVATAR = (() => {
const CHARS = [
  { id: 'f1', label: 'Longo liso', eyes: [[51.5, 40.2], [76.5, 37.2]], refs: [131.2, 28.1, 39.6], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f2', label: 'Cacheado', eyes: [[50.8, 46.4], [75.6, 43.2]], refs: [126.1, 25.7, 40.9], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f3', label: 'Black power', eyes: [[50.7, 53.0], [75.7, 49.3]], refs: [118.9, 29.0, 42.1], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f4', label: 'Tranças', eyes: [[50.9, 40.8], [75.5, 37.2]], refs: [114.7, 26.9, 46.9], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f5', label: 'Coque', eyes: [[49.6, 58.2], [76.8, 54.4]], refs: [123.3, 30.0, 43.2], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f6', label: 'Chanel', eyes: [[49.6, 48.5], [78.3, 47.0]], refs: [125.2, 32.5, 43.5], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f7', label: 'Ondulado', eyes: [[51.4, 45.2], [77.4, 41.6]], refs: [121.0, 40.7, 40.7], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'f8', label: 'Lenço', eyes: [[49.9, 41.2], [74.5, 38.4]], refs: [137.5, 84.8, 41.4], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm1', label: 'Cacheado', eyes: [[50.7, 41.6], [75.5, 43.7]], refs: [129.7, 23.9, 51.4], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm2', label: 'Degradê', eyes: [[50.7, 44.5], [78.5, 42.7]], refs: [110.7, 33.4, 57.9], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm3', label: 'Black power', eyes: [[52.0, 46.9], [74.7, 46.3]], refs: [114.1, 28.1, 52.9], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm4', label: 'Dreads', eyes: [[51.4, 46.2], [75.0, 44.4]], refs: [103.6, 25.1, 43.7], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm5', label: 'Franja', eyes: [[52.1, 42.2], [76.4, 40.0]], refs: [112.5, 39.5, 39.5], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm6', label: 'Topete', eyes: [[52.7, 46.3], [74.9, 47.3]], refs: [117.4, 34.1, 41.3], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm7', label: 'Ondulado', eyes: [[49.7, 45.9], [76.4, 43.1]], refs: [118.7, 37.5, 37.5], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' },
  { id: 'm8', label: 'Crespo', eyes: [[50.8, 42.6], [76.4, 40.4]], refs: [116.4, 30.1, 39.6], img: 'data:image/png;base64,', mask: 'data:image/png;base64,' }];

const R = 128;
const SKIN = ['#F6D2B5', '#EDB990', '#D9A070', '#C3824F', '#A8683C', '#8A522D', '#6B3D22', '#4C2A17'];
const HAIR = ['#1C1420', '#3B2318', '#6B3D22', '#B0441F', '#E0B25A', '#CFC8CD', '#FF5FA8', '#2FD0FF'];
const SCARF = ['#C0502A', '#2A2533', '#F4EDE4', '#FF2E93', '#22E3FF', '#FFB02E', '#7B3FE4', '#59C96B'];
const EYE = ['#2B1A12', '#6B3B1E', '#B5782A', '#3D8C4A', '#3F7FD6', '#6D7A86'];
const NOMES_CABELO = ['Preto', 'Castanho-escuro', 'Castanho', 'Ruivo', 'Loiro', 'Grisalho', 'Rosa', 'Azul'];
const NOMES_LENCO = ['Terracota', 'Preto', 'Branco', 'Rosa', 'Ciano', 'Amarelo', 'Roxo', 'Verde'];
const NOMES_OLHO = ['Castanho-escuro', 'Castanho', 'Mel', 'Verde', 'Azul', 'Cinza'];
const BG_NAMES = { 1: 'Mercado Público', 2: 'Parque Redenção', 3: 'Beira-Rio', 4: 'Usina do Gasômetro', 5: 'Arena do Grêmio', 6: 'Aeroporto' };
const byId = id => CHARS.find(c => c.id === id) || CHARS[0];
const rgb = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];

/* Receita: cores em null mantêm as do desenho original */
const DEFAULT = { char: 'f1', skin: null, hair: null, eyes: null, glasses: false, bg: 4 };
function normalize(c) {
  if (!c || typeof c !== 'object' || !c.char) return { ...DEFAULT };
  const idx = (v, n) => (Number.isInteger(v) && v >= 0 && v < n ? v : null);
  return { char: byId(c.char).id, skin: idx(c.skin, SKIN.length), hair: idx(c.hair, HAIR.length), eyes: idx(c.eyes, EYE.length), glasses: c.glasses === true, bg: BG_NAMES[c.bg] ? c.bg : 4 };
}

/* Carrega cada retrato e sua máscara uma vez (pixels em memória) */
const loadImg = src => new Promise((ok, fail) => { const i = new Image(); i.onload = () => ok(i); i.onerror = fail; i.src = src; });
const pixelsOf = img => { const cv = document.createElement('canvas'); cv.width = cv.height = R; const x = cv.getContext('2d'); x.drawImage(img, 0, 0); return x.getImageData(0, 0, R, R).data; };
const data = {};
function charData(id) {
  if (!data[id]) { const ch = byId(id); data[id] = Promise.all([loadImg(ch.img), loadImg(ch.mask)]).then(([a, b]) => ({ ch, px: pixelsOf(a), mk: pixelsOf(b) })); }
  return data[id];
}

/* Recolore: mantém luz e sombra (luminância relativa ao tom médio da região) e põe a cor nova */
function tone(r, g, b, target, ref, cap = 9) {
  const rel = Math.min(cap, (0.299 * r + 0.587 * g + 0.114 * b) / ref);
  const over = Math.max(0, Math.min(0.5, (rel - 1.5) * 0.3));   // só os brilhos mais fortes clareiam
  return target.map(t => Math.min(255, t * rel) * (1 - over) + 255 * over);
}
function drawGlasses(out, eyes) {
  const put = (x, y, c, a = 1) => {
    x = Math.round(x); y = Math.round(y); if (x < 0 || y < 0 || x >= R || y >= R) return;
    const i = (y * R + x) * 4; if (!out[i + 3]) return;
    for (let k = 0; k < 3; k++) out[i + k] = out[i + k] * (1 - a) + c[k] * a;
  };
  const frame = [26, 16, 34], hi = [92, 74, 120], glint = [235, 245, 255];
  const [[lx, ly], [rx, ry]] = eyes;
  const hw = Math.max(5.5, (rx - lx) * 0.29), hh = hw * 0.62;
  for (const [cx, cy] of eyes) {
    const x0 = Math.round(cx - hw), x1 = Math.round(cx + hw), y0 = Math.round(cy - hh - 0.5), y1 = Math.round(cy + hh);
    for (let x = x0 + 1; x < x1; x++) for (let y = y0 + 1; y < y1; y++) put(x, y, [200, 225, 255], 0.08);   // lente
    for (let x = x0 + 1; x < x1; x++) { put(x, y0, frame); put(x, y1, frame); put(x, y0 + 1, hi, 0.35); }
    for (let y = y0 + 1; y < y1; y++) { put(x0, y, frame); put(x1, y, frame); }
    put(x0 + 2, y0 + 2, glint, 0.85); put(x0 + 3, y0 + 2, glint, 0.6); put(x0 + 2, y0 + 3, glint, 0.6);   // brilho
  }
  const by = Math.round((ly + ry) / 2 - hh * 0.35);
  for (let x = Math.round(lx + hw) + 1; x < Math.round(rx - hw); x++) put(x, by, frame);   // ponte
  for (let k = 1; k <= 3; k++) { put(Math.round(lx - hw) - k, Math.round(ly - hh * 0.4), frame); put(Math.round(rx + hw) + k, Math.round(ry - hh * 0.4), frame); }   // hastes
}
const cache = new Map();
async function render(c) {
  c = normalize(c);
  const key = JSON.stringify([c.char, c.skin, c.hair, c.eyes, c.glasses]);
  if (cache.has(key)) return cache.get(key);
  const { ch, px, mk } = await charData(c.char);
  const out = new Uint8ClampedArray(px);
  const hairPal = ch.id === 'f8' ? SCARF : HAIR;
  const layers = [[0, c.skin === null ? null : rgb(SKIN[c.skin])], [1, c.hair === null ? null : rgb(hairPal[c.hair])], [2, c.eyes === null ? null : rgb(EYE[c.eyes])]];
  for (let i = 0; i < R * R; i++) {
    const p = i * 4; if (!out[p + 3]) continue;
    for (const [k, target] of layers) {
      const w = mk[p + k] / 255; if (!target || w < 0.05) continue;
      const t = tone(px[p], px[p + 1], px[p + 2], target, ch.refs[k], w < 0.9 ? 1.6 : 9);   // luz de borda: brilho contido
      out[p] = px[p] * (1 - w) + t[0] * w; out[p + 1] = px[p + 1] * (1 - w) + t[1] * w; out[p + 2] = px[p + 2] * (1 - w) + t[2] * w;
    }
  }
  if (c.glasses) drawGlasses(out, ch.eyes);
  const cv = document.createElement('canvas'); cv.width = cv.height = R;
  cv.getContext('2d').putImageData(new ImageData(out, R, R), 0, 0);
  if (cache.size > 120) cache.clear();
  cache.set(key, cv);
  return cv;
}
/** Desenha o personagem num canvas (recorte opcional [x, y, lado] em pixels de 128). */
function paint(canvas, c, crop) {
  const token = (canvas._avTok = (canvas._avTok || 0) + 1);
  return render(c).then(cv => {
    if (canvas._avTok !== token) return;
    const [sx, sy, s] = crop || [0, 0, R], ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false; ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(cv, sx, sy, s, s, 0, 0, canvas.width, canvas.height);
  });
}

/* Cenários: as cenas das missões reduzidas a 128 px (viram pixel art ao ampliar) */
const bgCache = {};
function bgCanvas(n) {
  if (!bgCache[n]) bgCache[n] = loadImg(IMG.scene[n]).then(img => {
    const side = Math.min(img.width, img.height), cv = document.createElement('canvas'); cv.width = cv.height = R;
    const ctx = cv.getContext('2d'); ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(img, (img.width - side) / 2, (img.height - side) / 2, side, side, 0, 0, R, R);
    return cv;
  }).catch(() => null);
  return bgCache[n];
}
/** Personagem sobre o cenário escolhido, num quadrado de `size` px. */
async function compose(c, size = 512) {
  c = normalize(c);
  const out = document.createElement('canvas'); out.width = out.height = size;
  const ctx = out.getContext('2d'); ctx.imageSmoothingEnabled = false;
  const bg = await bgCanvas(c.bg);
  if (bg) ctx.drawImage(bg, 0, 0, size, size); else { ctx.fillStyle = '#2B0B4F'; ctx.fillRect(0, 0, size, size); }
  const fade = ctx.createLinearGradient(0, 0, 0, size); fade.addColorStop(0.55, 'rgba(26,8,51,0)'); fade.addColorStop(1, 'rgba(26,8,51,.45)');
  ctx.fillStyle = fade; ctx.fillRect(0, 0, size, size);
  ctx.drawImage(await render(c), 0, 0, size, size);
  return out;
}

/* ---------- Tela "Crie seu personagem" ---------- */
let cfg = { ...DEFAULT }, tab = 'personagem';
const el = id => document.getElementById(id);
const TABS = [['personagem', 'Personagem'], ['cores', 'Cores'], ['fundo', 'Fundo']];
const FACE = [16, 4, 96];
const charBtn = ch => `<button type="button" class="av-opt" data-g="char" data-v="${ch.id}" aria-pressed="${cfg.char === ch.id}"><canvas width="128" height="128" data-char="${ch.id}" aria-hidden="true"></canvas><span>${ch.label}</span></button>`;
const sw = (g, i, col, on, name) => `<button type="button" class="av-sw" data-g="${g}" data-v="${i}" aria-pressed="${on}" aria-label="${name}" title="${name}" style="background:${col}"></button>`;
const origSw = g => `<button type="button" class="av-sw av-sw--orig" data-g="${g}" data-v="" aria-pressed="${cfg[g] === null}" aria-label="Cor original do desenho" title="Original">✦</button>`;
function renderTabs() { el('av-tabs').innerHTML = TABS.map(([id, n]) => `<button type="button" class="av-tab" role="tab" data-t="${id}" aria-selected="${id === tab}">${n}</button>`).join(''); }
function renderPanel() {
  let h = '';
  if (tab === 'personagem') h = `<h2>Feminino</h2><div class="av-grid">${CHARS.filter(c => c.id[0] === 'f').map(charBtn).join('')}</div>
    <h2>Masculino</h2><div class="av-grid">${CHARS.filter(c => c.id[0] === 'm').map(charBtn).join('')}</div>`;
  if (tab === 'cores') {
    const scarf = cfg.char === 'f8';
    h = `<h2>Pele</h2><div class="av-sws">${origSw('skin')}${SKIN.map((c, i) => sw('skin', i, c, cfg.skin === i, `Tom ${i + 1}`)).join('')}</div>
    <h2>${scarf ? 'Lenço' : 'Cabelo'}</h2><div class="av-sws">${origSw('hair')}${(scarf ? SCARF : HAIR).map((c, i) => sw('hair', i, c, cfg.hair === i, (scarf ? NOMES_LENCO : NOMES_CABELO)[i])).join('')}</div>
    <h2>Olhos</h2><div class="av-sws">${origSw('eyes')}${EYE.map((c, i) => sw('eyes', i, c, cfg.eyes === i, NOMES_OLHO[i])).join('')}</div>
    <h2>Óculos</h2><div class="av-toggle" role="group" aria-label="Óculos">
      <button type="button" class="btn btn--outline btn--sm" data-g="glasses" data-v="0" aria-pressed="${!cfg.glasses}">Sem óculos</button>
      <button type="button" class="btn btn--outline btn--sm" data-g="glasses" data-v="1" aria-pressed="${cfg.glasses}">Com óculos</button></div>`;
  }
  if (tab === 'fundo') h = `<h2>Onde você está</h2><div class="av-grid">${Object.entries(BG_NAMES).map(([n, name]) => `<button type="button" class="av-opt av-opt--bg" data-g="bg" data-v="${n}" aria-pressed="${cfg.bg === Number(n)}"><canvas width="128" height="128" data-bg="${n}" aria-hidden="true"></canvas><span>${name}</span></button>`).join('')}</div>`;
  el('av-panel').innerHTML = h;
  el('av-panel').querySelectorAll('canvas[data-char]').forEach(cv => paint(cv, { ...cfg, char: cv.dataset.char, hair: cv.dataset.char === 'f8' && cfg.char !== 'f8' ? null : cfg.hair }, FACE));
  el('av-panel').querySelectorAll('canvas[data-bg]').forEach(cv => bgCanvas(Number(cv.dataset.bg)).then(bg => { if (bg) { const x = cv.getContext('2d'); x.imageSmoothingEnabled = false; x.drawImage(bg, 0, 0, cv.width, cv.height); } }));
}
function update() {
  paint(el('av-canvas'), cfg);
  bgCanvas(cfg.bg).then(bg => { if (bg) el('av-mirror').style.backgroundImage = `url(${bg.toDataURL()})`; });
}
const any = n => Math.floor(Math.random() * n);
function setup() {
  el('av-tabs').addEventListener('click', e => { const t = e.target.closest('[data-t]'); if (!t) return; tab = t.dataset.t; renderTabs(); renderPanel(); });
  el('av-panel').addEventListener('click', e => {
    const b = e.target.closest('[data-g]'); if (!b) return;
    const g = b.dataset.g, v = b.dataset.v;
    if (g === 'char') { if ((v === 'f8') !== (cfg.char === 'f8')) cfg.hair = null; cfg.char = v; }
    else if (g === 'glasses') cfg.glasses = v === '1';
    else if (g === 'bg') cfg.bg = Number(v);
    else cfg[g] = v === '' ? null : Number(v);
    update(); renderPanel();
  });
  el('av-random').addEventListener('click', () => {
    cfg = normalize({ char: CHARS[any(CHARS.length)].id, skin: any(SKIN.length), hair: Math.random() < 0.4 ? null : any(HAIR.length), eyes: Math.random() < 0.5 ? null : any(EYE.length), glasses: Math.random() < 0.3, bg: cfg.bg });
    update(); renderPanel();
  });
  CHARS.forEach(c => charData(c.id));   // decodifica os retratos de antemão
}
return {
  setup, compose, paint, normalize,
  load(c) { cfg = normalize(c); tab = 'personagem'; renderTabs(); renderPanel(); update(); },
  get: () => ({ ...cfg }),
};
})();
